mapper.select:
SELECT COALESCE(SUM(stars_lit), 0)
FROM user_starlit_progress
WHERE user_id = #{userId}

SELECT COALESCE(SUM(p.stars_lit), 0)
FROM user_starlit_progress p
INNER JOIN starlit_pack k ON k.id = p.pack_id
WHERE p.user_id = #{userId}

    AND k.pack_key IN

        #{pk}

SELECT u.user_id AS userId, COALESCE(NULLIF(TRIM(u.nickname), ''), CONCAT('用户', u.user_id)) AS displayName, COALESCE(SUM(p.stars_lit), 0) AS totalStars FROM user u INNER JOIN user_starlit_progress p ON p.user_id = u.user_id
INNER JOIN starlit_pack k ON k.id = p.pack_id AND k.pack_key IN
#{pk}
GROUP BY u.user_id, u.nickname HAVING totalStars > 0 ORDER BY totalStars DESC, u.user_id ASC LIMIT #{limit}
